where $N=\lfloor n/2 \rfloor$, $\wt{\boldsymbol{\Sigma}}=\dfrac pN \sum_{i=1}^N \dfrac{\Delta\ol{{\bf X}}_{2i} \Delta\ol{{\bf X}}_{2i}^T}{|\Delta\ol{{\bf X}}_{2i}|^2} $.

Then the averaged nonlinear shrinkage (ANS) estimator of ICV is defined as
\begin{equation*}
\wh{\boldsymbol{\Sigma}}_{\textrm{ANS}}:= \hat{\theta}_p\cdot\frac{1}{B} \sum_{k=1}^B \hbSigma^{(k)}_{\textrm{ANS}}, ~~\hbSigma^{(k)}_{\textrm{ANS}} = \widetilde{\bf U}_1^{(k)} \textrm{diag}((\widetilde{\bf U}_1^{(k)})^{{\mathrm{T}}} \wt{\boldsymbol{\Xi}}_2^{(k)}\widetilde{\bf U}_1^{(k)}) (\widetilde{\bf U}_1^{(k)})^{{\mathrm{T}}},
\end{equation*}
where $\textrm{diag}({\bf A})$ sets all non-diagonal elements of matrix ${\bf A}$ to zero.

theorem.raw:
\label{thm:LSD_TVA}
Suppose that Assumptions \eqref{asm:class_c}--\eqref{asm:moment_L} hold.
Then, almost surely, the ESDs of ICV and ${\mathcal A}_N$ converge to probability distributions $H$ and $F^{{\mathcal A}}$, respectively, where
\begin{equation}
H(x)=\breve{H}(x/\theta), ~~~ \textrm{for all } x\geq 0 ~ \textrm{with} ~ \theta=\int_0^1 (\gamma_t^*)^2 dt,
\label{eq: determine of H}
\end{equation}
and $F^{{\mathcal A}}$ and $H$ are related as follows:
\[
m_{{\mathcal A}}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tilde{\theta}_f/\theta\cdot\tau(1 - \rho(1 + zm_{{\mathcal A}}(z))) - z}dH(\tau), ~~~~ \textrm{for} ~ z\in \mathbb{C}^+,
\]
where  $\tilde{\theta}_f = \int_0^1 (\dfrac 13 + \dfrac 16 f_{2,s}^*)(\gamma_s^*)^2ds$ and $m_{{\mathcal A}}(z)$ denotes the Stieltjes transform of $F^{{\mathcal A}}$.

Suppose that Assumptions \eqref{asm:class_c}-\eqref{asm:LSD_bH} and \eqref{asm:error}-\eqref{asm:interval} hold.
Then, as $p\to\infty$, the ESDs of ICV and ${\mathcal{\bm B}}_M$ converge almost surely to probability distributions $H$ and $F^{{\mathcal{\bm B}}}$, respectively, where $H$ satisfies \eqref{eq: determine of H} and $F^{{\mathcal{\bm B}}}$ is determined by $H$ in that its Stieltjes transform, $m_{{\mathcal{\bm B}}}(z)$, satisfies the Mar\v{c}enko--Pastur equation,
\begin{equation}\label{eq: m-p equation}
m_{{\mathcal{\bm B}}}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tau(1 - c(1 + zm_{{\mathcal{\bm B}}}(z))) - z}dH(\tau),\hspace{0.2cm}\text{for}~z\in \mathbb{C^{+}}.
\end{equation}
\label{thm: theorem for the TVAPA}

\label{thm: theorem for the TVAPA asynt}
Suppose that Assumptions \eqref{asm:class_c}--\eqref{asm:LSD_bH} and \eqref{asm:error}--\eqref{asm:bdd_L} hold.
Further, assume that $\max\limits_{1\leq i \leq n, 1\leq q\leq  p} nh(s_{T_i}^{(q)} - t_i) \to 0 $, almost surely.
Then, as $p\to\infty$, the ESDs of ICV and ${\mathcal{\bm B}}_M^*$ converge almost surely to probability distributions $H$ and $F^{{\mathcal{\bm B}}^*}$, respectively, where $H$ satisfies \eqref{eq: determine of H} and $F^{{\mathcal{\bm B}}^*}$ is determined by $H$ in that its Stieltjes transform $m_{{\mathcal{\bm B}}^*}(z)$ satisfies the Mar\v{c}enko--Pastur equation,
\begin{equation}
m_{{\mathcal{\bm B}}^*}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tau(1 - c(1 + zm_{{\mathcal{\bm B}}^*}(z))) - z}dH(\tau),\hspace{0.2cm}\text{for}~z\in \mathbb{C^{+}}.
\end{equation}

lemma.raw:
\label{lem:LSD ttSigma}
Under the assumptions of Theorem \ref{thm: theorem for the TVAPA}, the ESD of $\hbSigma$ converges almost surely, and the limit $F^{\hbSigma}$ is determined by  $\breve{H}$ in that its Stieltjes transform $m_{\hbSigma}(z)$ satisfies the following equation:
\begin{equation}m_{\hbSigma}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tau(1 - c(1 + zm_{\hbSigma}(z))) - z}d\breve{H}(\tau),\hspace{0.2cm}\text{for}~z\in \mathbb{C^+}.
\label{eq:LSD of ttF}
\end{equation}

\label{lem:theta estimation}
Under the assumptions of Theorem \ref{thm: theorem for the TVAPA}, we have
\begin{equation}\lim_{p\to\infty}3\frac{\sum_{i=1}^\hv|\Delta\wwbY_{2i}|^2}{p} =  \theta, \hspace{0.5cm}\text{almost surely}.
\label{eq: convergence of k avergence of wwX norm}
\end{equation}

(Lemma 1 in \cite{ZhengandLi20112}). Suppose that for each $p$, ${\bf v}_l = (v_l^1, \cdots, v_l^p)^\mathrm{T}$ and $\bm w_l = (w_l^1,\cdots,w_l^p)^{\mathrm{T}},l =1, \cdots, m$, are all $p$-dimensional vectors. Define
\[\bm{\widetilde{S}}_m = \sum_{l=1}^m (\bm v_l + \bm w_l)(\bm v_l + \bm w_l)^\mathrm{T} \text{~and~} \bm S_m = \sum_{l=1}^mw_l(w_l)^\mathrm{T}.\]
Suppose the following conditions are satisfied:
\begin{itemize}
  \item $m = m(p)$ with $\lim_{p\to\infty} p/m = c >0$;
  \item there exists a sequence $\epsilon_p = o(1/\sqrt{p})$ such that for all $p$ and all $l$, all the entries of $\bm v_l$ are bounded by $\epsilon_p$ in absolute value;
  \item $\lim\sup_{p\to\infty}\begin{rm}tr\end{rm}(\bm S_m)/p<\infty$ almost surely.
\end{itemize}
Then $L(F^{\bm{\widetilde{S}}_m}, F^{\bm S_m}) \to 0$ almost surely, where for any two probability distribution functions $F$ and $G$, $L(F, G)$ denotes the Levy distance between them.
\label{lem: appendix B lemma 1}

proposition.raw:
Under the assumptions of Theorem \ref{thm:LSD_TVA}, the ESD of $\widetilde{\boldsymbol{\Sigma}}$, $F^{\widetilde{\boldsymbol{\Sigma}}}$  converges almost surely to the limit $\widetilde{F}$, which is determined by $\breve{H}$ in that its Stieltjes transform $m_{\widetilde{F}}(z)$ satisfies the following equation:
\begin{equation}m_{\widetilde{F}}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tau(1 - \rho(1 + zm_{\widetilde{F}}(z))) - z}d\breve{H}(\tau),~\text{for}~z\in \mathbb{C}^+.
\label{eq: converfence of proposition A1}
\end{equation}
\label{prop: convergence of tilde sigma}

Under the assumptions of Theorem \ref{thm:LSD_TVA},
the ESD of the ICV matrix converges almost surely in distribution to a probability distribution $H$ as $p\to\infty$ defined by
\begin{equation}
H(x) = \breve{H}(x/\theta),
\label{eq: the relationship of ICV and H}
\end{equation}
where $\theta = \int_0^1(\gamma_t^*)^2dt$.
Moreover,
