\lim\limits_{p\to\infty} \frac{1}{p}\sum_{i = 1}^N |\Delta\wbX_{2i}|^2 =  \int_0^1 (\dfrac 13 + \dfrac 16 f_{2,s}^*)(\gamma_s^*)^2ds,\hspace{0.5cm} \text{almost surely}.
\label{eq: convergence of Vi plus lambda Zi}
\end{equation}
\label{prop: convergence of wi}

