\begin{defn} \label{def: rho-misiing}
For a stationary time series $(U_k),k\in \mathbb{Z}$, let $\mathcal{F}_j^\ell$ be the $\sigma$-field generated by the random variables $(U_k: -\infty\leq j\leq k \leq \ell\leq\infty)$.
The $\rho$-mixing coefficients are defined as
\[\rho(r) = \sup\limits_{f\in\mathcal{L}^2(\mathcal{F}_{-\infty}^0) ,~~ g\in \mathcal{L}^2(\mathcal{F}_{r}^\infty)} |\begin{rm}Corr\end{rm}(f,g)|, \hspace{0.5cm} \text{for} \hspace{0.5cm} r\in\mathbb{N},\]
where, for any probability space $\Omega$, $\mathcal{L}^2(\Omega)$ refers to the space of square-integrable, $\Omega$-measurable random variables.
\end{defn}
\begin{compactenum}\setcounter{enumi}{2}
\item[]
\begin{compactenum}
    \item\label{asm:error} For all $j= 1,\cdots,p$, the noise $(\varepsilon_t^{(j)})$ is a stationary time series with mean 0 and has bounded $4\ell$th moments and $\rho$-mixing coefficients $\rho^{(j)}(r)$ satisfying $\max_{j=1,\cdots,p} \rho^{(j)}(r) = O(r^{-\ell})$ for some integer $\ell>2$;
    \item\label{asm:dim_windows} $h =\lfloor \xi n^{\beta} \rfloor$ for some $\xi\in(0,\infty)$ and $\beta \in ((3+\ell)/(2\ell +2), 1)$, and $\hv = \lfloor n/(2h)\rfloor$ satisfy that $\lim_{p\to\infty} p/\hv = c >0$, where $\ell$ is the integer in Assumption \eqref{asm:error};
    \item\label{asm:bdd_L}  there exists a constant $L^*<\infty$ such that  $\sup\limits_{1\leq i \leq n} L_i\leq L^*$, almost surely;
    \item\label{asm:interval}   $\max\limits_{1\leq i \leq n} n(s_{T_i} - s_{T_{i-1}}) \to 1$, almost surely, as $n\to \infty$.
\end{compactenum}
\end{compactenum}

It is well known that the LSDs of a sample covariance matrix ${\bf S}_N$ and the underlying population covariance matrix ICV are related through the Mar\v{c}enko--Pastur equation from Theorem 1.1 of \cite{Silverstein1995}, which coincides with the result of Corollary \ref{cor:LSD_ATVA}.
We set $p = 100$ and $n = 390$, which represents the case where 100 stocks are recorded per minute within one trading day.
