\end{equation}
where $x_1,\cdots, x_{2p}$ are chosen to be equally spaced in the interval $[\min(\lambda({\tilde{\mathcal{\bm A}}}_N), \lambda({\bf S}_N) )$, $\max(\lambda({\tilde{\mathcal{\bm A}}}_N), \lambda({\bf S}_N) )]$, where $\lambda({\bf A})$ denotes the spectral of any symmetric matrix ${\bf A}$.
