The convergence of the ESD of the ICV was proved in Theorem \ref{thm:LSD_TVA}.
The rest of Theorem \ref{thm: theorem for the TVAPA} is a direct consequence of the following two lemmas.
\begin{lem}\label{lem:LSD ttSigma}
Under the assumptions of Theorem \ref{thm: theorem for the TVAPA}, the ESD of $\hbSigma$ converges almost surely, and the limit $F^{\hbSigma}$ is determined by  $\breve{H}$ in that its Stieltjes transform $m_{\hbSigma}(z)$ satisfies the following equation:
\begin{equation}m_{\hbSigma}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tau(1 - c(1 + zm_{\hbSigma}(z))) - z}d\breve{H}(\tau),\hspace{0.2cm}\text{for}~z\in \mathbb{C^+}.
\label{eq:LSD of ttF}
\end{equation}

\end{lem}

\begin{lem}\label{lem:theta estimation}
Under the assumptions of Theorem \ref{thm: theorem for the TVAPA}, we have
\begin{equation}\lim_{p\to\infty}3\frac{\sum_{i=1}^\hv|\Delta\wwbY_{2i}|^2}{p} =  \theta, \hspace{0.5cm}\text{almost surely}.
\label{eq: convergence of k avergence of wwX norm}
\end{equation}
\end{lem}

\no\emph{Proof of Lemma \ref{lem:LSD ttSigma}.}
To prove the convergence of $F^{\hbSigma}$, we shall show that
\[
\hbSigma = \frac{p}{\hv} \sum_{i=1}^\hv\frac{\Delta\twbY_{2i}(\Delta\twbY_{2i})^{\mathrm{T}}}{|\Delta\twbY_{2i}|^2}~~~\text{and}~~~
\ttbSigma := \frac{p}{\hv}\sum_{i=1}^{\hv}\frac{\Delta\twbX_{2i}\Delta\twbX_{2i}^{\mathrm{T}}}{|\Delta\twbX_{2i}|^2}
\]
have the same LSD.
Following the same arguments as in the proof of Proposition C.1 of \cite{XiaandZheng20182}, it suffices to show that
\begin{equation}
\max\limits_{1\leq i \leq \hv, 1\leq j \leq p} \frac{\sqrt{p}|\Delta\twbe_{2i}^{(j)}|}{|\Delta\twbX_{2i}|}\to 0,\hspace{1cm} \text{almost surely}.
\label{eq: convergence og delta epsilon divided by delta x}
\end{equation}
We start by showing that there exists a constant $\widetilde{C}>0$ for large $M$, such that
\begin{equation}\label{eq: minimun of twbX}
\min\limits_{1\leq i \leq M} |\Delta\twbX_{2i}|^2 \geq \widetilde{C}.
\end{equation}


By equation \eqref{eqn:Delta_V}, we decompose $\Delta\twbX_{2i}$ as follows:
\begin{align*}
\Delta\twbX_{2i}= & \frac{1}{h}\sum_{j=1}^{h}\left(\wbX_{(2i-1)h + j} - \wbX_{(2i-2)h}\right) - \frac{1}{h}\sum_{j=1}^{h}\left( \wbX_{(2i-2)h+j} -  \wbX_{(2i-2)h}\right) \notag\\
= & \sum_{l=1}^{2h}\left (1 - \frac{|h-l+1|}{h} \right)\Delta\wbX_{(2i-2)h+l}\notag\\
= & \sum_{l=1}^{2h}\left(1 - \frac{|h-l+1|}{h} \right)\sum_{j=1}^{L_{(2i-2)h+l}}a_{(2i-2)h+l,j}\Delta_{(2i-2)h+l,j}{\bf X}\notag\\
&+\sum_{l=1}^{2h-1}\left(1 - \frac{|h-l|}{h} \right )\sum_{j=1}^{L_{(2i-2)h+l}}b_{(2i-2)h+l,j}\Delta_{(2i-2)h+l,j}{\bf X}.\\
\end{align*}
From the fact that  $a_{i,j} + b_{i,j} = 1$, we can further write $ \Delta\twbX_{2i}$ as

\begin{align}\label{eq: expression for tbwX}
\Delta\twbX_{2i} = & \frac{1}{h}\sum_{j=1}^{L_{2ih}}a_{2ih,j}\Delta_{2ih,j}{\bf X} \notag\\
&+ \sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left(1-\frac{|h-l+1|}{h}\right)\Delta_{(2i-2)h+l,j}{\bf X} \notag\\
&+ \sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[ \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right]\Delta_{(2i-2)h+l,j}{\bf X} \notag\\
:= & \tbV_i + \sqrt{\psi_i}\boldsymbol{\Lambda}\tbZ_i,
\end{align}
where
\begin{align*}
\psi_i &:= \frac{1}{h^2}\sum_{j=1}^{L_{2ih}}a_{2ih,j}^2\int_{s_{T_{2ih-1} + j - 1}}^{s_{T_{2ih-1} + j}}\gamma_t^2dt\\
&+\sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[\left(1-\frac{|h-l+1|}{h}\right) + \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right]^2\\
&\hspace{2cm}\cdot\int_{s_{T_{(2i-2)h+l-1} + j - 1}}^{s_{T_{(2i-2)h+l-1} + j}} \gamma_t^2dt,
\end{align*}
\begin{align*}
\tbZ_i& := \frac{1}{\sqrt{\psi_i}}\frac{1}{h}\sum_{j=1}^{L_{2ih}}a_{2ih,j}\int_{s_{T_{2ih-1} + j - 1}}^{s_{T_{2ih-1} + j}}\gamma_td{\bf W}_t\notag\\
&+\sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[\left(1-\frac{|h-l+1|}{h}\right) + \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right] \\
&\hspace{2cm}\cdot\int_{s_{T_{(2i-2)h+l-1} + j - 1}}^{s_{T_{(2i-2)h+l-1} + j}} \gamma_td{\bf W}_t,
\end{align*}
and
\begin{align*}
\tbV_i &:= \frac{1}{h}\sum_{j=1}^{L_{2ih}}a_{2ih,j}\int_{s_{T_{2ih-1} + j - 1}}^{s_{T_{2ih-1} + j}}\boldsymbol{\mu}_tdt\notag\\
&+\sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[\left(1-\frac{|h-l+1|}{h}\right) + \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right] \\
&\hspace{2cm}\cdot\int_{s_{T_{(2i-2)h+l-1} + j - 1}}^{s_{T_{(2i-2)h+l-1} + j}}\boldsymbol{\mu}_tdt.
\end{align*}
Without loss of generality, we may assume that $\gamma_t$ and ${\bf W}_t$ are independent, which leads to the fact that each entry of $\tbZ_i$ is i.i.d. standard normal.
Otherwise, by using a similar trick as in the proof of (3.34) of \cite{ZhengandLi20112}, we have
\begin{equation}\label{eq: norm convergeb=nce of tbZ}
\max\limits_{1\leq i \leq M} |\frac{1}{p}|\boldsymbol{\Lambda}\tbZ_i|^2  - 1 | \to 0, ~~~\text{almost surely}.
\end{equation}
Combining this with the fact that all the entries of $\tbV_i$ are of order $O(h/n) = o(1/\sqrt{p})$, we have
\begin{equation}
\frac{\sum_{i=1}^\hv|\Delta\twbX_{2i}|^2}{p} = \frac{\sum_{i=1}^\hv|\tbV_i + \sqrt{\psi_i}\boldsymbol{\Lambda}\tbZ_i|^2}{p} = \sum_{i=1}^\hv\psi_i + o_{a.s.}(1).
\label{eq: psii plus error term}
\end{equation}

Thus, from equation \eqref{eq: expression for tbwX},  we have
\[
|\Delta\twbX_{2i}|^2 = |\tbV_i + \sqrt{\psi_i}\boldsymbol{\Lambda}\tbZ_i|^2 \geq |\tbV_i|^2 + |\psi_i|\cdot| \boldsymbol{\Lambda}\tbZ_i|^2 - 2|\tbV_i| | \sqrt{\psi_i}\boldsymbol{\Lambda}\tbZ_i|.
\]
Assumption \eqref{asm:bdd_sigma} implies that for all $i$, there exists $C'$ such that$|\psi_i|\geq C'h/n.$
Taking this together with Assumption \eqref{asm:dim_windows} and Equation \eqref{eq: norm convergeb=nce of tbZ}, there exists $C^*>0$ such that for all $n$ large enough,
\[
\min\limits_{1\leq i \leq m}|\psi_i|\cdot| \boldsymbol{\Lambda}\tbZ_i|^2 \geq C^*.
\]
Moreover, $\max_i |\tbV_i| =O(\sqrt{p}\times h/n) = o(1)$ follows from Assumption \eqref{asm:bdd_mu}.
Therefore \eqref{eq: minimun of twbX} follows.
Next, we will show that
\begin{equation}\label{eq: sqrtt p delta twbe}
\max\limits_{1\leq i \leq M, 1\leq j \leq p} \sqrt{p}|\Delta \twbe_{2i}^{(j)} | \to 0, ~~~ \text{almost surely}.
\end{equation}
Observe that $(\bar{\varepsilon}_i^{(j)}) = (1/L_i\sum_{k=1}^{L_i}\varepsilon_{i,k}^{(j)})$ is also a $\rho$-mixing sequence following from Definition \ref{def: rho-misiing}, and the $\rho$-mixing coefficients $\bar{\rho}^j(r)$ based on $(\bar{\varepsilon}_i^{(j)})$ have the same order as $\rho^j(r)$ by the boundedness of $L_i$ from Assumption \eqref{asm:bdd_L}.
Therefore, \eqref{eq: sqrtt p delta twbe} follows by the same process used in (C.7) of \cite{XiaandZheng20182}, which, together with \eqref{eq: minimun of twbX}, implies that \eqref{eq: convergence og delta epsilon divided by delta x} holds.\proofend


\no\emph{Proof of Lemma \ref{lem:theta estimation}.}
Note that
\[\sum_{i=1}^\hv|\Delta\twbY_{2i}|^2 = \sum_{i=1}^\hv|\Delta\twbX_{2i}|^2 + 2\sum_{i=1}^\hv\Delta\twbX_{2i}^{\mathrm{T}}\Delta\twbe_{2i} + \sum_{i=1}^M|\Delta\twbe_{2i}|^2.
\]
The convergence of \eqref{eq: convergence og delta epsilon divided by delta x} implies that $\sum_{i=1}^M|\Delta \twbe_{2i}|^2/p \to 0$ almost surely.
It remains to prove that
\begin{equation}\label{eq: convergence of sum of TWBx}
\lim_{p\to\infty} 3\frac{\sum_{i=1}^\hv|\Delta\twbX_{2i}|^2}{p} = \theta, \hspace{1cm} \text{almost surely},
\end{equation}
and
\begin{equation}\label{eq: twbX plus twbe}
\frac{\sum_{i=1}^\hv\Delta\twbX_{2i}^{\mathrm{T}}\Delta\twbe_{2i}}{p}\to 0, \hspace{1cm}\text{almost surely}.
\end{equation}
To show \eqref{eq: convergence of sum of TWBx}, by \eqref{eq: psii plus error term}, it suffices to show that
\[
\lim_{n\to\infty}\sum_{i=1}^\hv\int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}}|\hv\psi_i - \frac{1}{3}(\gamma_s^*)^2|ds =0,
\]
almost surely.
Suppose that  $\gamma_t^*$ has $J$ jumps at $\{\tau_1,\cdots,\tau_J\}$; then
\begin{align*}
&\sum_{i=1}^\hv\int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}} |\hv\psi_i - \frac{1}{3}(\gamma_s^*)^2|ds\\
=&\sum\limits_{i \in \{\tau_1,\cdots,\tau_J\}}\int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}}|\hv\psi_i - \frac{1}{3}(\gamma_s^*)^2|ds \\
&+ \sum\limits_{i \notin \{\tau_1,\cdots,\tau_J\}}\int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}}|\hv\psi_i - \frac{1}{3}(\gamma_s^*)^2|ds \\
:= &\Delta_1 + \Delta_2.
\end{align*}
For any $\epsilon > 0$ and for sufficiently large $n$, $|\Delta_1| \leq \epsilon$ follows from the boundedness of $|M\psi_i|$ and $\gamma_t^*$.
For the second term, $\Delta_2$, by defining $\psi_i^*$ by replacing $\gamma_t$ with $\gamma_t^*$ from the definition of $\psi_i$, we have
\[
|\Delta_2| \leq \Delta_{21} + \Delta_{22} + \Delta_{23} +\Delta_{24},
\]
where
\[
\begin{split}
\Delta_{21} &:= \sum\limits_{i \notin \{\tau_1, \cdots, \tau_J\}} \int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}} |M\psi_i - M\psi_i^*|ds,\\
\Delta_{22} &:= \sum\limits_{i \notin \{\tau_1, \cdots, \tau_J\}} \int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}} | M\psi_i^* - M(\gamma_{(2i-2)/h}^*)^2A_i|ds,\\
\Delta_{23} &:= \sum\limits_{i \notin \{\tau_1, \cdots, \tau_J\}} \int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}} | M(\gamma_{(2i-2)/h}^*)^2A_i - M(\gamma_{s}^*)^2A_i |ds,\\
\Delta_{24} &:= \sum\limits_{i \notin \{\tau_1, \cdots, \tau_J\}} \int_{s_{T_{(2i-2)h}}}^{s_{T_{2ih}}} | M(\gamma_{s}^*)^2A_i - \frac{1}{3}(\gamma_{s}^*)^2 |ds,
\end{split}
\]
and
\[
\begin{split}
A_i := &\frac{1}{h^2} \sum_{j=1}^{L_{2ih}} a_{2ih,j}^2 \Delta s_{2ih,j} + \sum_{l=1}^{2h-1} \sum_{j=1}^{L_{(2i-2)h+l}} \Big[1 - \frac{|h-l+1|}{h}+ \\
&\hspace{1cm}+\frac{|h-l+1| - |h-l|}{h}b_{(2i-2)h+l,j} \Big]^2\Delta s_{(2i-2)h+l,j} .
\end{split}
\]
We further decompose $A_i$ as $A_i = A_{i1} +  A_{i2} + A_{i3}+ A_{i4}$, where
\begin{align*}
A_{i1} &:= \frac{1}{h^2} \sum_{j=1}^{L_{2ih}} a_{2ih,j}^2 \Delta s_{2ih,j} = O(\frac{1}{nh^2}),\\
A_{i2} &:= \sum_{l=1}^{2h-1} \left(1 - \frac{|h-l+1|}{h} \right)^2\sum_{j=1}^{L_{(2i-2)h+l}} \Delta s_{(2i-2)h+l,j}= \frac{2h}{3n} + o(\frac{h}{n}),\\
A_{i3} &:= \sum_{l=1}^{2h-1} \sum_{j=1}^{L_{(2i-2)h+l}} \frac{2}{h}\left(1 - \frac{|h-l+1|}{h} \right)(|h-l+1| - |h-l|) \\
&\cdot b_{(2i-2)h+l,j}\Delta s_{(2i-2)h+l,j} = O(\frac{1}{n}),\\
A_{i4} &:= \sum_{l=1}^{2h-1} \sum_{j=1}^{L_{(2i-2)h+l}} \frac{1}{h^2}(|h-l+1| - |h-l|)^2b_{(2i-2)h+l,j}^2\Delta s_{(2i-2)h+l,j} \\
&= O(\frac{1}{nh}),
\end{align*}
follow from the boundedness of $L_i$ both below and above, and $\Delta s_{i,j} = O(1/n)$ by Assumption \eqref{asm:interval}.
As $(\gamma_t^*)$ is continuous in $[s_{T_{(2i-2)h}}, s_{T_{2ih}}]$ when $i \notin \{\tau_1, \cdots, \tau_J\}$, $(\gamma_t)$ uniformly converges to $(\gamma_t^*)$  by Assumption \eqref{asm:bdd_sigma}, and $\psi_i^* = O(h/n)$ by Assumption \eqref{asm:bdd_gamma} and \eqref{asm:bdd_L}, for any $\epsilon >0 $ and sufficiently large $n,p$, it is easy to show that
\[
|MA_i - 1/3|\leq \epsilon ~~~\text{and}~~~\max\{\Delta_{21},\Delta_{22}, \Delta_{23},\Delta_{24}  \}<C\epsilon.
\]
This completes the proof of \eqref{eq: convergence of sum of TWBx}.
Finally, \eqref{eq: twbX plus twbe} follows from \eqref{eq: convergence of sum of TWBx} and \eqref{eq: convergence og delta epsilon divided by delta x}.\proofend

